        "story": "كان دخول سوق العمل (Berufseinstieg ist in) صعبًا على كارينا في بلد جديد، فقررت تقديم نفسها للوكالة (Agentur mit einem) بفيلم مميز. ولكن كان عليها أن تغير وزنها بشكل كبير (Gewicht stark verändern) من أجل دورها. وجدت كارينا أن الانتقال بين المدرسة (Wechsel zwischen Schule) ومواعيد التصوير مرهقًا، لكن في الحوارات (Dialogen darf man) يُسمح لها بابتكار شيء جديد. توصي كارينا بمشاهدة ممثلين آخرين في المسرح والأفلام (Schauspieler im Theater) لتطوير مهاراتها."
