        "text": "Gegen ein Team aus der Bundesliga und dann auch noch gegen die Bayern spielen zu können, ist wohl der Traum eines jeden Amateurvereins. Und es gibt ja auch Beispiele dafür, dass Amateure gegen die Großen aus der Profiliga achtbare Ergebnisse erreicht haben. Ist Ihr Team für die kommende Spielzeit gut gerüstet oder werden Sie Neuzugänge in Ihren Kader aufnehmen?",
        "pitch": 1.14,
        "rate": 0.96,
        "voice": "female"
