        "text": "Wir haben eine sehr flexible Mannschaft. Ich denke, wir können es uns leisten, in dieser Saison ein bisschen auszuprobieren, welches System für uns das erfolgreichste sein wird. Im Moment testen wir, ob wir mit Peter Krah, also mit nur einem Stürmer als Spitze, zurechtkommen. Bisher lief das ja hervorragend.",
        "pitch": 0.88,
