        "text": "Eindeutig in der Defensive. Unser Torwart Klaus Düringer und unsere Abwehr haben in dieser Saison noch keinen einzigen Gegentreffer hinnehmen müssen. In der ganzen vergangenen Saison hat Düringer gerade mal 23 Tore kassiert. Außerdem sind unsere Spieler außerordentlich diszipliniert. Jeder weiß genau, wo er hingehört.",
